#!/bin/sh

# delete the symlink on process exit
cleanup() {
  rm -f starnet2_weights.pb
}
trap cleanup RETURN EXIT SIGINT SIGKILL

# the binary hardcodes the weights path so we have to symlink it to the CWD
ln -sf "$HOMEBREW_PREFIX/Caskroom/starnet++/2,03,2022/StarNetv2CLI_MacOS/starnet2_weights.pb" .

# define a load path since the libs are not in the same dir as the bin
DYLD_LIBRARY_PATH=$HOMEBREW_PREFIX/Caskroom/starnet++/2,03,2022/StarNetv2CLI_MacOS command $HOMEBREW_PREFIX/Caskroom/starnet++/2,03,2022/StarNetv2CLI_MacOS/starnet++ $@
